def maxProfitAssignment(difficulty, profit, worker):
    jobs = sorted(zip(difficulty, profit))
    total = 0
    best = 0
    i = 0
    for ability in sorted(worker):
        while i < len(jobs) and jobs[i][0] <= ability:
            if jobs[i][1] > best:
                best = jobs[i][1]
            i += 1
        total += best
    return total
